import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int k = Integer.parseInt(firstLine[1]);
        String[] data = br.readLine().split(" ");
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(data[i]);
        }
        int[] oddEven = new int[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                oddEven[i] = (arr[i] % 2 == 0) ? 1 : -1;
            } else {
                oddEven[i] = (arr[i] % 2 == 0) ? oddEven[i - 1] + 1 : oddEven[i - 1] - 1;
            }
        }
        List<DiffNode> diffList = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            diffList.add(new DiffNode(Math.abs(arr[i + 1] - arr[i]), i));
        }
        Collections.sort(diffList, Comparator.comparingInt(a -> a.diff));
        int ans = 0;
        for (DiffNode d : diffList) {
            if (k >= d.diff && oddEven[d.indx] == 0) {
                k -= d.diff;
                ans++;
            }
        }
        pw.println(ans);
        pw.close();
    }

    static class DiffNode {
        int diff;
        int indx;
        DiffNode(int diff, int indx) {
            this.diff = diff;
            this.indx = indx;
        }
    }
}
