#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }
    vector<int> oddEven(n);
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            oddEven[i] = (arr[i] % 2 == 0) ? 1 : -1;
        } else {
            oddEven[i] = (arr[i] % 2 == 0) ? oddEven[i - 1] + 1 : oddEven[i - 1] - 1;
        }
    }
    struct DiffNode {
        int diff;
        int indx;
        DiffNode(int d, int i) : diff(d), indx(i) {}
    };
    vector<DiffNode> diffList;
    for (int i = 0; i < n - 1; i++) {
        diffList.emplace_back(abs(arr[i + 1] - arr[i]), i);
    }
    std::sort(diffList.begin(), diffList.end(), [](const DiffNode &a, const DiffNode &b) {
        return a.diff < b.diff;
    });
    int ans = 0;
    for (const auto &d : diffList) {
        if (k >= d.diff && oddEven[d.indx] == 0) {
            k -= d.diff;
            ans++;
        }
    }
    cout << ans << "\n";
    return 0;
}

